cd /app/povray-dl; python3 - <<'PY'
import json,subprocess,urllib.parse
def get(u):
    return subprocess.run(['curl','-s','--max-time','20',u],capture_output=True,text=True).stdout
for q in ['povray','"persistence of vision" 2.2','pov ray source 2.2']:
    u='https://archive.org/advancedsearch.php?q='+urllib.parse.quote(q)+'&fl[]=identifier&fl[]=title&output=json&rows=50'
    try:
        d=json.loads(get(u)); ids=[x['identifier'] for x in d['response']['docs']]
    except Exception as e:
        print(q,'parse err',e); continue
    print('=== q=%r -> %d ids ==='%(q,len(ids)))
    for i in ids:
        try:
            f=json.loads(get('https://archive.org/metadata/'+i+'/files'))['result']
            names=[x['name'] for x in f]; low=[n.lower() for n in names]
        except Exception:
            continue
        mark=[n for n in names if ('mak' in n.lower() or n.lower().endswith('.c') or 'povsrc' in n.lower() or 'machine' in n.lower())]
        if mark:
            print(' HIT',i,'::',mark[:10])
    print(' sweep done')
print('ALL SWEEP DONE')
PY

